INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การดูแลรักษาของใช้ส่วนตัว', 'easy', 'mcq', 'สิ่งของในข้อใดเป็น "ของใช้ส่วนตัว" ที่ไม่ควรใช้ร่วมกับผู้อื่นเพื่อป้องกันโรคติดต่อ?', '["โต๊ะอาหาร","แปรงสีฟัน, ผ้าเช็ดหน้า, ผ้าเช็ดตัว","โทรทัศน์","พัดลมเพดาน"]'::jsonb, 1, 'แปรงสีฟัน ผ้าเช็ดตัว ผ้าเช็ดหน้า หวี เป็นของใช้ส่วนตัวที่ไม่ควรใช้ปะปนกับผู้อื่นเพราะอาจแพร่กระจายเชื้อโรค'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดกระเป๋านักเรียน', 'easy', 'mcq', 'หลักการสำคัญที่สุดในการจัดกระเป๋านักเรียนให้ถูกสุขอนามัยและไม่ปวดหลังคือข้อใด?', '["ใส่หนังสือเรียนทุกเล่มตั้งแต่ ป.1 ถึง ป.6 ลงในกระเป๋า","จัดสมุดและหนังสือตามตารางสอนในแต่ละวัน และเก็บของชิ้นหนักไว้ชิดแผ่นหลัง","ใส่ของเล่นและขนมให้เต็มกระเป๋า","ถือกระเป๋าด้วยมือข้างเดียวตลอดเวลา"]'::jsonb, 1, 'จัดหนังสือตามตารางเรียนทุกวันเพื่อไม่ให้กระเป๋าหนักเกินไป และวางของหนักแนบชิดหลังเพื่อรักษาสมดุลกระดูกสันหลัง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดโต๊ะเขียนหนังสือ', 'easy', 'mcq', 'การจัดวางหนังสือบนโต๊ะเขียนหนังสือควรจัดวางอย่างไรให้หยิบใช้สะดวกและเป็นระเบียบ?', '["วางกองซ้อนทับกันโดยไม่แยกประเภท","จัดเรียงหนังสือจากเล่มสูงไปเล่มต่ำ หันสันหนังสือออกด้านนอก และแยกประเภทสมุด-หนังสือ","วางหนังสือกระจัดกระจายบนเก้าอี้","คว่ำหน้าหนังสือเปิดทิ้งไว้"]'::jsonb, 1, 'การวางเรียงความสูงและหันสันหนังสือออกด้านนอกช่วยให้มองเห็นชื่อหนังสือและหยิบใช้งานได้สะดวก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดตู้เสื้อผ้า', 'medium', 'mcq', 'เสื้อผ้าประเภทใดควร "พับเก็บ" ใส่ลิ้นชัก แทนการแขวนด้วยไม้แขวนเสื้อ?', '["เสื้อเชิ้ตและชุดนักเรียน","เสื้อยืด, กางเกงขาสั้น, ชุดชั้นใน และถุงเท้า","เสื้อสูท","กระโปรงพลีทจีบ"]'::jsonb, 1, 'เสื้อยืดและชุดชั้นในควรพับเก็บเพื่อประหยัดเนื้อที่ตู้ ส่วนชุดนักเรียนและเสื้อเชิ้ตที่รีดแล้วควรแขวนเพื่อไม่ให้ยับ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกวาดบ้านและถูบ้าน', 'easy', 'mcq', 'ขั้นตอนการกวาดบ้านที่ถูกต้องตามหลักสุขาภิบาลควรเริ่มจากบริเวณใดก่อน?', '["กวาดจากชั้นล่างขึ้นชั้นบน","กวาดจากที่สูงลงที่ต่ำ (เช่น ปัดฝุ่นบนตู้ เพดาน แล้วจึงกวาดพื้น) และกวาดจากมุมห้องออกสู่ประตู","กวาดกระจายไปทั่วทุกทิศทางพร้อมกัน","ถูพื้นก่อนแล้วจึงค่อยกวาดขยะ"]'::jsonb, 1, 'ต้องปัดฝุ่นจากที่สูงลงสู่พื้นก่อน จากนั้นกวาดจากซอกมุมห้องมารวมกันตรงกลางหรือหน้าประตูเพื่อตักใส่ที่โกยขยะ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ไม้กวาดชนิดต่างๆ: ไม้กวาดดอกหญ้า', 'easy', 'mcq', '"ไม้กวาดดอกหญ้า" เหมาะสำหรับใช้กวาดพื้นผิวประเภทใด?', '["พื้นซีเมนต์หยาบนอกบ้านที่มีน้ำขัง","พื้นไม้, พื้นกระเบื้อง, พื้นหินขัดที่แห้งและเรียบภายในบ้าน","พื้นสนามหญ้าที่มีใบไม้ร่วง","พื้นดินเลน"]'::jsonb, 1, 'ไม้กวาดดอกหญ้ามีขนอ่อนนุ่ม เหมาะสำหรับกวาดฝุ่นละอองบนพื้นแห้งและเรียบภายในบ้าน ห้ามนำไปกวาดพื้นเปียกน้ำ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ไม้กวาดทางมะพร้าว', 'easy', 'mcq', 'หากต้องการกวาดใบไม้แห้งในสนามหญ้าหรือกวาดน้ำขังบนพื้นซีเมนต์ ควรเลือกใช้ไม้กวาดชนิดใด?', '["ไม้กวาดดอกหญ้า","ไม้กวาดทางมะพร้าว","ไม้กวาดขนไก่","ไม้ปัดหยากไย่"]'::jsonb, 1, 'ไม้กวาดทางมะพร้าวมีความแข็งและทนทาน เหมาะสำหรับกวาดพื้นซีเมนต์หยาบ พื้นดิน สนามหญ้า และพื้นเปียกน้ำ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การล้างจานชาม', 'easy', 'mcq', 'ก่อนนำจานชามไปล้างด้วยน้ำยาล้างจาน ขั้นตอนแรกที่ต้องทำคือข้อใด?', '["แช่น้ำร้อนทันที","กวาดเศษอาหารทิ้งลงในถังขยะ และล้างคราบสกปรกหยาบด้วยน้ำสะอาด 1 ครั้ง","ใช้น้ำยาล้างจานเทราดลงไปขณะมีเศษอาหาร","นำไปผึ่งแดดก่อน"]'::jsonb, 1, 'ต้องแยกกวาดเศษอาหารออกให้หมดก่อน แล้วล้างน้ำเปล่ารอบหนึ่ง จะช่วยให้ล้างคราบมันได้ง่ายขึ้นและท่อไม่อุดตัน'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซักรองเท้าผ้าใบนักเรียน', 'medium', 'mcq', 'การตากรองเท้าผ้าใบสีขาวหลังจากซักเสร็จ ควรปฏิบัติตามข้อใดเพื่อป้องกันรองเท้าเกิดคราบเหลือง?', '["ตากแดดจัดโดยไม่ต้องหุ้มอะไร","นำกระดาษทิชชูสีขาวมาพันหุ้มให้ทั่วรองเท้าก่อนนำไปตากแดด","อบในเตาไมโครเวฟ","แช่น้ำยาฟอกขาวทิ้งไว้ข้ามคืน"]'::jsonb, 1, 'การใช้กระดาษทิชชูสีขาวพันหุ้มรองเท้าผ้าใบ กระดาษทิชชูจะช่วยดูดซับคราบด่างของผงซักฟอก ป้องกันการเกิดคราบเหลือง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] สัญลักษณ์การดูแลรักษาเสื้อผ้า', 'hard', 'mcq', 'สัญลักษณ์รูป "เตารีดที่มีจุด 1 จุด (•)" บนป้ายฉลากเสื้อผ้า หมายความว่าอย่างไร?', '["ห้ามรีดเด็ดขาด","รีดด้วยอุณหภูมิต่ำ (ความร้อนต่ำ)","รีดด้วยอุณหภูมิปานกลาง","รีดด้วยอุณหภูมิสูงสุด"]'::jsonb, 1, 'จุด 1 จุด หมายถึง อุณหภูมิต่ำ (สำหรับผ้าใยสังเคราะห์ ไนลอน), 2 จุด = ปานกลาง (ผ้าขนสัตว์ ผ้าไหม), 3 จุด = สูง (ผ้าฝ้าย ลินิน)'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การจัดห้องนอน', 'easy', 'mcq', 'หลังจากตื่นนอนในตอนเช้า สิ่งที่นักเรียนควรทำทันทีคือข้อใด?', '["วิ่งไปเปิดโทรทัศน์","พับผ้าห่ม จัดหมอนและดึงผ้าปูที่นอนให้ตึงเรียบร้อย","กระโดดลงจากเตียงแล้วออกจากบ้านทันที","โยนหมอนลงบนพื้น"]'::jsonb, 1, 'การเก็บที่นอน พับผ้าห่ม และจัดหมอนให้เรียบร้อยหลังตื่นนอน เป็นการสร้างวินัยและความเป็นระเบียบของตนเอง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การทำความสะอาดตู้เย็น', 'medium', 'mcq', 'ข้อใดเป็นการดูแลรักษาตู้เย็นที่ถูกต้องและประหยัดพลังงาน?', '["นำอาหารที่ยังร้อนจัดใส่ตู้เย็นทันที","เปิดประตูตู้เย็นทิ้งไว้เพื่อระบายความร้อน","ตรวจสอบอาหารหมดอายุทิ้งสม่ำเสมอ และละลายน้ำแข็งในช่องแช่แข็งเมื่อหนาเกินกำหนด","ตั้งตู้เย็นติดชิดผนังห้องโดยไม่เว้นช่องว่าง"]'::jsonb, 2, 'การละลายน้ำแข็งสม่ำเสมอและไม่ตั้งตู้เย็นชิดผนังเกินไปช่วยให้คอมเพรสเซอร์ระบายความร้อนได้ดีและประหยัดไฟ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การตากผ้า', 'easy', 'mcq', 'ก่อนนำเสื้อผ้าไปตากแดด ควรทำสิ่งใดเพื่อให้ผ้ายับน้อยลงและสีไม่ซีดจาง?', '["กลับเอาด้านในออกด้านนอก แล้วสะบัดผ้าก่อนพาดบนไม้แขวนเสื้อ","ขยำผ้าให้เป็นก้อนกลม","ตากในที่มืดสนิท","นำผ้าไปแช่น้ำมัน"]'::jsonb, 0, 'การกลับด้านในออกด้านนอกช่วยป้องกันแดดเลียสีผ้าให้ซีดจาง และการสะบัดผ้าช่วยคลายรอยยับทำให้รีดง่าย'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกำจัดกลิ่นอับในตู้เสื้อผ้า', 'medium', 'mcq', 'วัสดุธรรมชาติในข้อใดสามารถนำมาใส่ในตู้เสื้อผ้าเพื่อช่วยดูดซับกลิ่นอับชื้นได้ดี?', '["ถ่านหุงต้มหรือผงเบกกิ้งโซดา","เศษดินทราย","ใบไม้สดเปียกน้ำ","น้ำส้มคั้น"]'::jsonb, 0, 'ถ่านไม้มีรูพรุนขนาดเล็กจำนวนมาก ช่วยดูดซับกลิ่นอับชื้นและความชื้นในตู้เสื้อผ้าได้อย่างปลอดภัย'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การล้างห้องน้ำอย่างปลอดภัย', 'medium', 'mcq', 'ในการใช้น้ำยาล้างห้องน้ำที่มีฤทธิ์เป็นกรด ควรสวมใส่อุปกรณ์ป้องกันใดเพื่อความปลอดภัย?', '["ถุงมือยาง, รองเท้าบูทยาง และหน้ากากอนามัย","ถุงมือผ้าบางๆ","แว่นตากันแดด","ชุดนอน"]'::jsonb, 0, 'กรดในน้ำยาล้างห้องน้ำกัดกร่อนผิวหนังและไอระเหยเป็นอันตรายต่อระบบทางเดินหายใจ จึงต้องสวมถุงมือและรองเท้ายาง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การดูแลรักษากล่องดินสอ', 'easy', 'mcq', 'เพื่อป้องกันไม่ให้กระเป๋าหรือกล่องดินสอเปรอะเปื้อนคราบหมึก ควรทำอย่างไร?', '["เปิดปลอกปากกาทิ้งไว้เสมอ","ปิดฝาปลอกปากกาและสวมปลอกดินสอให้เรียบร้อยทุกครั้งหลังใช้งาน","เหลาดินสอจนแหลมทิ่มทะลุกล่อง","ทิ้งไส้ดินสอกดไว้ในกล่อง"]'::jsonb, 1, 'การสวมปลอกดินสอและปิดปลอกปากกาช่วยป้องกันไส้ดินสอหักและป้องกันน้ำหมึกเลอะสิ่งของ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การประหยัดน้ำในงานบ้าน', 'easy', 'mcq', 'น้ำสุดท้ายจากการล้างจานหรือซักผ้า สามารถนำไปใช้ประโยชน์ต่อได้อย่างไร?', '["เททิ้งลงบนถนน","นำไปรดน้ำต้นไม้หรือล้างพื้นบริเวณรอบบ้าน","นำมาใช้ดื่ม","นำมาใช้ทำอาหาร"]'::jsonb, 1, 'น้ำซักล้างที่ไม่ปนเปื้อนสารเคมีอันตรายสามารถนำมารดน้ำต้นไม้หรือล้างลานซีเมนต์เพื่อประหยัดน้ำได้'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การแยกขยะในบ้าน', 'easy', 'mcq', 'เปลือกผลไม้และเศษอาหารจากห้องครัวควรคัดแยกไว้ในถังขยะประเภทใดเพื่อนำไปทำปุ๋ยหมัก?', '["ขยะเปียกหรือขยะอินทรีย์","ขยะรีไซเคิล","ขยะอันตราย","ขยะติดเชื้อ"]'::jsonb, 0, 'ขยะเปียกหรือขยะอินทรีย์ย่อยสลายได้ง่าย เหมาะสำหรับนำไปทำปุ๋ยหมักบำรุงดิน'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ไม้ดอกและไม้ประดับ', 'easy', 'mcq', 'ข้อใดเป็น "ไม้ดอก" (พืชที่ปลูกเพื่อชื่นชมความสวยงามของดอก)?', '["ดาวเรือง, กุหลาบ, มะลิ, กล้วยไม้","พลูด่าง, สาวน้อยปะแป้ง, ลิ้นมังกร","ผักบุ้ง, คะน้า","ต้นยางพารา, ต้นปาล์ม"]'::jsonb, 0, 'ดาวเรือง กุหลาบ มะลิ มีดอกสวยงามมีกลิ่นหอม จัดเป็นไม้ดอก ส่วนพลูด่าง ลิ้นมังกร เน้นใบสวยงามจัดเป็นไม้ประดับ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ไม้ประดับ (Foliage plants)', 'easy', 'mcq', 'พืชในข้อใดจัดเป็น "ไม้ประดับ" ที่นิยมปลูกเพื่อชมความสวยงามของใบและลำต้น?', '["ดอกบัว","พลูด่าง และ เฟิร์นข้าหลวง","ดอกชบา","มะลิซ้อน"]'::jsonb, 1, 'พลูด่างและเฟิร์นข้าหลวงมีใบและทรงพุ่มที่สวยงาม จึงนิยมปลูกประดับตกแต่งอาคารสถานที่'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: ช้อนปลูก', 'easy', 'mcq', '"ช้อนปลูก" มีหน้าที่ในการใช้งานตรงกับข้อใด?', '["ตัดแต่งกิ่งไม้ขนาดใหญ่","ใช้ขุดหลุมปลูก ย้ายต้นกล้า และตักดินใส่กระถาง","รดน้ำต้นกล้าขนาดเล็ก","ดายหญ้าในแปลงกว้าง"]'::jsonb, 1, 'ช้อนปลูกมีใบมีดโค้งมน ใช้ขุดย้ายต้นกล้าและคลุกเคล้าดินปลูกในแปลงหรือกระถางขนาดเล็ก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: ส้อมพรวน', 'easy', 'mcq', '"ส้อมพรวน" ใช้สำหรับทำงานเกษตรในด้านใด?', '["พรวนดินรอบโคนต้นพืชให้ร่วนซุย","ตัดกิ่งไม้ที่แห้งตาย","ตักน้ำรดต้นไม้","ขุดบ่อปลาขนาดใหญ่"]'::jsonb, 0, 'ส้อมพรวนมีซี่เหล็ก 3 ซี่ ใช้สำหรับพรวนดินรอบๆ โคนต้นพืชให้ดินโปร่ง ร่วนซุย ระบายน้ำและอากาศได้ดี'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: บัวรดน้ำ', 'easy', 'mcq', 'เครื่องมือใดเหมาะที่สุดสำหรับรดน้ำ "ต้นกล้าอ่อน" เพื่อไม่ให้ลำต้นหักโค่นและดินกระจาย?', '["สายยางฉีดน้ำแรงดันสูง","บัวรดน้ำที่มีฝักบัวกระจายน้ำเป็นฝอยนุ่มนวล","ขันตักน้ำสาด","เครื่องสูบน้ำ"]'::jsonb, 1, 'บัวรดน้ำกระจายสายน้ำเป็นเม็ดฝอยละเอียด ช่วยให้ต้นกล้าอ่อนไม่ช้ำและดินไม่กระเด็น'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: กรรไกรตัดกิ่ง', 'easy', 'mcq', 'เมื่อต้องการตัดแต่งกิ่งไม้ที่มีขนาดเล็กหรือตัดดอกไม้แห้งทิ้ง ควรเลือกใช้เครื่องมือใด?', '["มีดดายหญ้า","กรรไกรตัดกิ่ง","ขวาน","เลื่อยลันดา"]'::jsonb, 1, 'กรรไกรตัดกิ่งมีสปริงช่วยผ่อนแรง ใช้สำหรับตัดแต่งกิ่งไม้ที่มีเส้นผ่านศูนย์กลางไม่เกิน 1 นิ้ว'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การดูแลรักษาเครื่องมือเกษตรที่มีคม', 'medium', 'mcq', 'หลังใช้งานจอบ เสียม และช้อนปลูกเสร็จแล้ว ควรทำความสะอาดและบำรุงรักษาอย่างไรก่อนจัดเก็บ?', '["ล้างคราบดินออก เช็ดให้แห้ง ทาน้ำมันกันสนิม และแขวนเก็บเข้าที่","วางทิ้งไว้บนพื้นดินกลางแจ้ง","แช่น้ำไว้ในถัง","ล้างด้วยน้ำยาล้างห้องน้ำ"]'::jsonb, 0, 'ต้องล้างดินออก เช็ดให้แห้งสนิท ชโลมน้ำมันหล่อลื่นกันสนิม เพื่อยืดอายุการใช้งานและป้องกันอุบัติเหตุ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเตรียมดินปลูกต้นไม้ในกระถาง', 'medium', 'mcq', 'ก่อนใส่ดินลงในกระถางปลูก ควรใช้วัสดุใดรองก้นกระถางเพื่อป้องกันดินไหลออกและช่วยระบายน้ำ?', '["เศษกระเบื้องแตกหรือกาบมะพร้าวสับ","ถุงพลาสติกทึบ","แผ่นเหล็ก","กระดาษหนังสือพิมพ์"]'::jsonb, 0, 'เศษกระถางแตกหรือกาบมะพร้าวสับช่วยปิดรูก้นกระถางไม่ให้ดินร่วง แต่ยอมให้น้ำส่วนเกินระบายออกได้ดี'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ดินที่เหมาะแก่การปลูกพืช', 'easy', 'mcq', 'ดินชนิดใดมีความเหมาะสมที่สุดสำหรับการปลูกไม้ดอกไม้ประดับทั่วไป?', '["ดินร่วนที่มีอินทรียวัตถุ (ซากพืชซากสัตว์) ผสม","ดินทรายล้วนๆ","ดินเหนียวจัดแข็งตัว","ดินลูกรัง"]'::jsonb, 0, 'ดินร่วนมีความโปร่ง อุ้มน้ำและระบายน้ำได้พอเหมาะ และมีธาตุอาหารสมบูรณ์ที่สุดสำหรับพืช'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การรดน้ำต้นไม้', 'easy', 'mcq', 'ช่วงเวลาใดเหมาะสมที่สุดสำหรับการรดน้ำต้นไม้ในแต่ละวัน?', '["เวลากลางคืนดึกสงัด","เวลาเช้าตรู่ (06.00-08.00 น.) และเวลาบ่ายแก่ๆ (16.00-17.00 น.)","เวลาเที่ยงวันแดดจัด","รดน้ำทุกๆ 1 ชั่วโมง"]'::jsonb, 1, 'ควรรดน้ำตอนเช้าและตอนเย็น แดดไม่แรง ทำให้น้ำไม่ระเหยเร็วและใบพืชไม่ไหม้เหี่ยวเฉา'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การใส่ปุ๋ยบำรุงต้นไม้', 'medium', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการใส่ปุ๋ยให้แก่ต้นไม้คือข้อใด?', '["ไม่ควรโรยปุ๋ยชิดโคนต้นไม้โดยตรง เพราะจะทำให้โคนต้นไหม้และตายได้","ต้องใส่ปุ๋ยวันละ 3 เวลา","ห้ามรดน้ำตามหลังใส่ปุ๋ย","ต้องใส่ปุ๋ยเฉพาะตอนกลางคืน"]'::jsonb, 0, 'ควรโรยปุ๋ยรอบๆ ชายพุ่มของต้นไม้ ไม่ควรใส่ชิดโคนต้นโดยตรงเพราะความเข้มข้นของปุ๋ยอาจทำให้รากและโคนเน่าไหม้'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกำจัดวัชพืช', 'easy', 'mcq', '"วัชพืช" หมายถึงอะไร และส่งผลเสียต่อพืชที่เราปลูกอย่างไร?', '["แมลงที่มากินใบพืช","พืชที่เราไม่ต้องการ (เช่น หญ้า) ที่แย่งน้ำ แสงแดด และธาตุอาหารจากต้นไม้หลัก","ปุ๋ยชนิดหนึ่ง","เชื้อราในดิน"]'::jsonb, 1, 'วัชพืชคือพืชที่ขึ้นเองโดยไม่ได้เพาะปลูก เช่น หญ้าแห้วหมู หญ้าคา คอยแย่งน้ำและอาหารของพืชปลูก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การขยายพันธุ์พืช: การปักชำ', 'medium', 'mcq', 'พืชในข้อใดสามารถขยายพันธุ์ได้ง่ายด้วยวิธี "การตัดกิ่งปักชำ"?', '["ต้นคุณนายตื่นสาย, ต้นพลูด่าง, ชบา","ต้นมะพร้าว","ต้นข้าวโพด","ต้นทุเรียน"]'::jsonb, 0, 'คุณนายตื่นสาย พลูด่าง ชบา สามารถตัดกิ่งสมบูรณ์มาปักลงในดินร่วนหรือแช่น้ำแล้วออกรากใหม่ได้ง่าย'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ปุ๋ยอินทรีย์', 'easy', 'mcq', 'ปุ๋ยชนิดใดจัดเป็น "ปุ๋ยคอก"?', '["ปุ๋ยเคมีสูตร 15-15-15","มูลสัตว์ต่างๆ เช่น ขี้วัว ขี้ไก่ ขี้ค้างคาว","เศษใบไม้หมัก","ปุ๋ยยูเรียเม็ดสีขาว"]'::jsonb, 1, 'ปุ๋ยคอกได้จากมูลสัตว์ต่างๆ เช่น มูลวัว มูลไก่ มูลสุกร ช่วยปรับปรุงโครงสร้างดินให้ร่วนซุย'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ประโยชน์ของไม้ดอกไม้ประดับ', 'easy', 'mcq', 'ข้อใดเป็นประโยชน์ของไม้ดอกไม้ประดับต่อสุขภาพจิตของมนุษย์?', '["ช่วยให้สถานที่ดูสดชื่น สวยงาม สบายตา และผ่อนคลายความตึงเครียด","ทำให้บ้านมีราคาแพงขึ้นพันเท่า","ช่วยป้องกันน้ำท่วมโลก","ทำให้ไม่ต้องทำความสะอาดบ้าน"]'::jsonb, 0, 'สีสันและความเขียวขจีของต้นไม้ช่วยฟอกอากาศ สร้างความร่มรื่น และช่วยให้จิตใจผ่อนคลาย'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การพรวนดิน', 'easy', 'mcq', 'เหตุใดเราจึงต้อง "พรวนดิน" รอบโคนต้นพืชอย่างสม่ำเสมอ?', '["เพื่อให้ดินร่วนซุย อากาศและน้ำซึมผ่านไปยังรากพืชได้สะดวก","เพื่อตัดรากพืชทิ้งทั้งหมด","เพื่อทำให้ดินแข็งตัวดั่งหิน","เพื่อเปลี่ยนสีของดิน"]'::jsonb, 0, 'การพรวนดินช่วยทำลายหน้าดินที่แน่นทึบ ทำให้ออกซิเจนและน้ำซึมลงสู่รากพืชได้ง่ายขึ้น'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] น้ำหมักชีวภาพ (EM)', 'medium', 'mcq', 'น้ำหมักชีวภาพทำมาจากสิ่งใด และมีประโยชน์อย่างไร?', '["ทำจากเศษพืช ผัก ผลไม้ หมักร่วมกับกากน้ำตาล ช่วยย่อยสลายอินทรียวัตถุและบำรุงดินอย่างปลอดภัย","ทำจากสารเคมีสังเคราะห์เข้มข้น","ทำจากน้ำมันเบนซิน","ทำจากผงซักฟอก"]'::jsonb, 0, 'น้ำหมักชีวภาพเกิดจากการหมักเศษพืชผักกับกากน้ำตาล มีจุลินทรีย์ที่มีประโยชน์ช่วยปรับปรุงดินและขับไล่แมลงศัตรูพืช'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การเก็บเกี่ยวผลผลิตดอกไม้', 'easy', 'mcq', 'การตัดดอกไม้เพื่อนำไปปักแจกัน ควรตัดในลักษณะใดเพื่อให้ดูดน้ำได้ดีและอยู่ได้นาน?', '["ตัดกิ่งในแนวเฉียง 45 องศาในน้ำสะอาด","หักกิ่งด้วยมือแรงๆ","ทุบก้านดอกให้แหลกละเอียด","ใช้ไฟลนปลายก้านดอก"]'::jsonb, 0, 'การตัดก้านดอกในแนวเฉียงช่วยเพิ่มพื้นที่ผิวในการดูดน้ำของท่อลำเลียง และตัดในน้ำเพื่อป้องกันฟองอากาศอุดตันท่อ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่างพื้นฐาน: ค้อนหงอน', 'easy', 'mcq', '"ค้อนหงอน" มีประโยชน์หลักตรงกับข้อใด?', '["ใช้ตัดแผ่นไม้","ใช้ตอกตะปูและใช้หงอนค้อนสำหรับถอนตะปู","ใช้ขันนอตหัวแฉก","ใช้วัดความยาว"]'::jsonb, 1, 'ด้านหน้าของค้อนหงอนใช้สำหรับตอกตะปู ส่วนด้านหลังที่เป็นง่ามงอโค้ง (หงอน) ใช้สำหรับถอนตะปู'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่าง: ไขควงปากแบนและปากแฉก', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับขันหรือคลายสกรูที่มีรอยผ่าบนหัวสกรูเป็นรูปเครื่องหมายบวก (+)?', '["ไขควงปากแบน","ไขควงปากแฉก (Phillips screwdriver)","คีมปากจิ้งจก","ประแจเลื่อน"]'::jsonb, 1, 'ไขควงปากแฉกมีปลายแฉก 4 แฉก ใช้สำหรับขันหรือคลายสกรูหัวแฉก (+)'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่าง: คีมรวม (คีมปากจิ้งจก)', 'medium', 'mcq', '"คีมปากจิ้งจก" นิยมใช้ในงานช่างลักษณะใด?', '["ใช้จับ ยึด ดัด บิด และตัดเส้นลวดขนาดเล็ก","ใช้ทุบทำลายกำแพงปูน","ใช้ไถปรับหน้าไม้","ใช้วัดระดับน้ำ"]'::jsonb, 0, 'คีมปากจิ้งจกเป็นคีมอเนกประสงค์ ใช้คีบจับชิ้นงาน ดัดสายไฟ และมีรอยตัดสำหรับตัดลวดขนาดเล็ก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือวัด: ตลับเมตร', 'easy', 'mcq', 'เมื่อต้องการวัดความยาวของโต๊ะเรียนหรือความกว้างของห้องเรียน ควรเลือกใช้เครื่องมือวัดใด?', '["ไม้บรรทัดพลาสติกสั้น 15 ซม.","ตลับเมตร (Tape measure)","วงเวียน","สายวัดรอบเอว"]'::jsonb, 1, 'ตลับเมตรมีความยาว 3-5 เมตรขึ้นไป แถบวัดทำจากเหล็กสปริงม้วนเก็บได้ เหมาะสำหรับวัดงานก่อสร้างและชิ้นงานขนาดใหญ่'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซ่อมแซมสันหนังสือที่ชำรุด', 'easy', 'mcq', 'หากพบว่าปกสมุดหรือสันหนังสือเรียนฉีกขาด ควรซ่อมแซมด้วยวัสดุอุปกรณ์ใด?', '["ใช้เชือกฟางมัดรอบเล่ม","ใช้เทปกาวใสหรือเทปผ้าติดสัน และกรรไกรตัดแต่งให้เรียบร้อย","ใช้ตะปูตอกตรึง","ใช้กาวตราช้างหยอดจนเปียกโชก"]'::jsonb, 1, 'การใช้เทปกาวใสหรือเทปแลคซีนติดยึดสันหนังสือที่ขาดช่วยให้หนังสือกลับมาแข็งแรงและเปิดอ่านได้ตามเดิม'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซ่อมแซมขาเก้าอี้ไม้ที่โยกคลอน', 'medium', 'mcq', 'เมื่อขาโต๊ะหรือเก้าอี้ไม้ที่บ้านมีสกรูหลวมจนโยกคลอน ควรทำอย่างไรเป็นอันดับแรก?', '["ใช้ค้อนทุบขาเก้าอี้ทิ้ง","ใช้ไขควงที่ขนาดพอดีกับหัวสกรู ขันให้แน่นเข้าที่เดิม","นำเทปกาวกระดาษมาพันรอบขาเก้าอี้","ทิ้งเก้าอี้แล้วซื้อใหม่ทันที"]'::jsonb, 1, 'การใช้ไขควงขันสกรูที่คลายตัวให้แน่นขึ้นเป็นทักษะงานช่างพื้นฐานที่ช่วยยืดอายุการใช้งานเฟอร์นิเจอร์'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากวัสดุเหลือใช้', 'easy', 'mcq', 'การนำ "ขวดน้ำพลาสติกที่ไม่ใช้แล้ว" มาตัดทำเป็นกระถางต้นไม้แขวน จัดเป็นกิจกรรมที่ตรงกับข้อใด?', '["การทำลายทรัพยากร","การประดิษฐ์ของใช้จากวัสดุเหลือใช้ (Upcycling / Reuse)","การสร้างมลพิษ","การสิ้นเปลืองเวลา"]'::jsonb, 1, 'การนำขวดพลาสติกเหลือใช้มาประดิษฐ์เป็นกระถางต้นไม้ ช่วยลดปริมาณขยะ ประหยัดค่าใช้จ่าย และส่งเสริมความคิดสร้างสรรค์'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากวัสดุธรรมชาติ: ใบตอง', 'easy', 'mcq', 'งานประดิษฐ์ใบตองในข้อใดนิยมใช้ในวันลอยกระทง?', '["กระทงลอยจากหยวกกล้วยและกลีบใบตอง","พานพุ่ม","บายศรีสู่ขวัญ","มาลัยคล้องคอ"]'::jsonb, 0, 'กระทงใบตองใช้วัสดุธรรมชาติย่อยสลายได้ง่าย เช่น หยวกกล้วยและใบตองพับเป็นกลีบผกาหรือกลีบกุหลาบ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากกะลามะพร้าว', 'medium', 'mcq', 'ผลิตภัณฑ์ของใช้ในข้อใดที่นิยมนำ "กะลามะพร้าวขัดมัน" มาประดิษฐ์?', '["กระบวยตักน้ำ, โคมไฟ, กระปุกออมสิน","เสื้อกันฝน","รองเท้าผ้าใบ","กระจกมองหลัง"]'::jsonb, 0, 'กะลามะพร้าวมีความแข็ง เหนียว ทนทาน เมื่อขูดขัดผิวให้เรียบมันจะสวยงาม นิยมทำกระบวยตักน้ำ ถ้วย และโคมไฟ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] กาวชนิดต่างๆ: กาวลาเท็กซ์', 'easy', 'mcq', '"กาวลาเท็กซ์ (กาวสีขาว)" เหมาะสำหรับใช้ติดวัสดุประเภทใดในงานประดิษฐ์?', '["กระดาษ, ผ้า, และไม้","แผ่นเหล็กหนา","แผ่นกระจกเงา","ท่อน้ำพีวีซี"]'::jsonb, 0, 'กาวลาเท็กซ์เป็นกาวน้ำสูตรน้ำ เหมาะสำหรับติดวัสดุที่มีรูพรุน เช่น กระดาษ ไม้ ผ้า และติดแน่นเมื่อแห้ง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ปืนกาวร้อน (Hot Glue Gun)', 'medium', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการใช้ "ปืนกาวร้อน" ในการทำงานประดิษฐ์คือข้อใด?', '["ห้ามสัมผัสปลายโลหะและกาวร้อนที่ไหลออกมาเพราะอาจทำให้ผิวหนังพุพองไหม้ได้","ห้ามเสียบปลั๊กไฟ","ห้ามใช้กับริบบิ้นผ้า","ห้ามวางบนแท่นวาง"]'::jsonb, 0, 'ปลายปืนกาวและแท่งกาวที่ละลายมีความร้อนสูงมาก หากสัมผัสจะทำให้เกิดแผลไหม้พุพองได้'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ขั้นตอนการทำงานประดิษฐ์', 'medium', 'mcq', 'ขั้นตอนแรกสุดในกระบวนการทำงานประดิษฐ์ของใช้คือข้อใด?', '["ลงมือตัดวัสดุทันที","การกำหนดปัญหา ความต้องการ และวางแผนออกแบบร่างแบบชิ้นงาน","การประเมินราคาขาย","การนำไปจัดแสดง"]'::jsonb, 1, 'ต้องเริ่มจากการคิดวิเคราะห์ความต้องการ ออกแบบร่างแบบ (Sketch) และวางแผนเตรียมวัสดุก่อนลงมือทำจริง'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความปลอดภัยในการใช้เครื่องมือช่าง', 'easy', 'mcq', 'การส่งมีดคัตเตอร์หรือกรรไกรให้เพื่อนอย่างปลอดภัย ควรส่งอย่างไร?', '["หันปลายแหลมคมไปทางเพื่อน","โยนข้ามโต๊ะไปให้เพื่อน","หันด้านด้ามจับไปให้เพื่อนรับ และเก็บใบมีดเข้าฝักให้สนิทก่อนส่ง","ถือวิ่งไปส่งอย่างรวดเร็ว"]'::jsonb, 2, 'ต้องเก็บคมมีดเข้าฝัก และหันด้านด้ามจับไปให้เพื่อนเสมอ เพื่อป้องกันของมีคมบาดมือ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความปลอดภัยจากเครื่องใช้ไฟฟ้า', 'easy', 'mcq', 'พฤติกรรมในข้อใดเสี่ยงต่อการถูก "กระแสไฟฟ้าดูด" เสียชีวิต?', '["ใช้ผ้าแห้งเช็ดปลั๊กไฟ","ใช้มือที่เปียกน้ำจับเต้าเสียบหรือกดสวิตช์ไฟ","ดึงที่ตัวปลั๊กเมื่อต้องการถอดสายไฟ","ปิดสวิตช์ก่อนถอดปลั๊ก"]'::jsonb, 1, 'น้ำเป็นตัวนำไฟฟ้าที่ดีมาก การใช้มือเปียกสัมผัสอุปกรณ์ไฟฟ้าอาจทำให้กระแสไฟฟ้ารั่วไหลเข้าสู่ร่างกายได้ทันที'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การจัดเก็บเครื่องมือช่าง', 'easy', 'mcq', 'หลังจากใช้งานเครื่องมือช่างเสร็จแล้ว ควรจัดเก็บอย่างไรจึงจะถูกต้องและปลอดภัย?', '["วางเกลื่อนกลาดไว้บนพื้นทางเดิน","ทำความสะอาด เช็ดน้ำมันกันสนิม และจัดเก็บเข้ากล่องเครื่องมือหรือแขวนบนแผงเครื่องมืออย่างเป็นระเบียบ","โยนรวมกันไว้ในถังขยะ","เก็บไว้ใต้เตียงนอน"]'::jsonb, 1, 'การเก็บเข้ากล่องหรือแขวนบนแผงเป็นระเบียบ ช่วยป้องกันอุบัติเหตุสะดุดหกล้ม และทำให้หยิบใช้งานได้สะดวกในครั้งต่อไป'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] มารยาทในการทำงานร่วมกับผู้อื่น', 'easy', 'mcq', 'เมื่อทำงานกลุ่มร่วมกับเพื่อนในวิชาการงานอาชีพ ข้อใดเป็นมารยาทการทำงานที่ดีที่สุด?', '["รับผิดชอบหน้าที่ของตนเอง รับฟังความคิดเห็นของเพื่อน และช่วยเหลือซึ่งกันและกัน","ปล่อยให้เพื่อนสนิททำคนเดียว","สั่งการเพื่อนโดยไม่ช่วยลงมือทำ","แย่งผลงานเพื่อนมาเป็นของตนเอง"]'::jsonb, 0, 'การมีความรับผิดชอบต่อหน้าที่ที่ได้รับมอบหมาย มีน้ำใจ และรับฟังความคิดเห็นของเพื่อนร่วมกลุ่มคือกุญแจสู่ความสำเร็จ'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การตรงต่อเวลาในการทำงาน', 'easy', 'mcq', 'การส่งงานประดิษฐ์ตรงตามกำหนดเวลา มีประโยชน์ต่อนักเรียนอย่างไร?', '["แสดงถึงความรับผิดชอบ การมีวินัยในตนเอง และฝึกนิสัยการทำงานอย่างมืออาชีพ","ทำให้ได้รางวัลใหญ่จากรัฐบาล","ทำให้ไม่ต้องสอบปลายภาค","ทำให้คุณครูเกรงใจ"]'::jsonb, 0, 'การตรงต่อเวลาสะท้อนถึงการบริหารเวลาที่ดี ความซื่อสัตย์ และความรับผิดชอบต่อภาระหน้าที่'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การใช้วัสดุอย่างคุ้มค่าและประหยัด', 'easy', 'mcq', 'ในการตัดกระดาษสีเพื่อทำงานประดิษฐ์ ควรตัดอย่างไรจึงจะประหยัดและเหลือเศษทิ้งน้อยที่สุด?', '["ตัดตรงกลางแผ่นกระดาษใหญ่ทันที","วาดแบบร่างชิดมุมหรือขอบกระดาษก่อนตัด เพื่อให้เหลือก้นกระดาษผืนใหญ่ไว้ใช้ต่อ","ฉีกกระดาษเป็นชิ้นเล็กๆ ทั้งแผ่น","ใช้กระดาษแผ่นละ 1 ชิ้นงาน"]'::jsonb, 1, 'การร่างแบบชิดขอบหรือมุมกระดาษช่วยลดการสิ้นเปลือง และทำให้เหลือพื้นที่กระดาษส่วนที่เหลือไปทำงานชิ้นอื่นต่อได้'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การประเมินผลงาน', 'medium', 'mcq', 'หลังจากประดิษฐ์ชิ้นงานเสร็จสิ้นแล้ว การทดลองใช้งานจริงมีประโยชน์อย่างไร?', '["เพื่อตรวจหาข้อบกพร่องและนำไปปรับปรุงแก้ไขให้ชิ้นงานมีความแข็งแรงทนทานใช้งานได้จริง","เพื่อถ่ายรูปลงโซเชียลเท่านั้น","เพื่อให้พังแล้วจะได้ทำใหม่","ไม่มีประโยชน์ใดๆ"]'::jsonb, 0, 'การทดสอบประสิทธิภาพจริงทำให้ทราบจุดอ่อนของชิ้นงาน เช่น รอยต่อไม่แน่น กาวหลุด เพื่อนำไปปรับปรุงให้สมบูรณ์'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเย็บผ้าพื้นฐาน: การสอยผ้า', 'hard', 'mcq', 'การซ่อมแซมชายกระโปรงหรือชายกางเกงนักเรียนที่ด้ายหลุดลุ่ย โดยไม่ต้องการให้เห็นรอยด้ายที่ด้านหน้า นิยมใช้วิธีการเย็บแบบใด?', '["การด้นถอยหลัง","การสอยซ่อนด้าย","การเนาเท่ากัน","การปักทึบ"]'::jsonb, 1, 'การสอยซ่อนด้าย (Blind stitch) ใช้สำหรับเก็บริมผ้า ชายกระโปรง ชายกางเกง โดยรอยด้ายจะซ่อนอยู่ด้านใน ไม่เห็นที่ด้านนอก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเย็บผ้าพื้นฐาน: การเนา', 'medium', 'mcq', 'การ "เนาผ้า" มีจุดประสงค์เพื่ออะไรก่อนการเย็บจริง?', '["เพื่อยึดผ้าสองชิ้นให้อยู่ติดกันชั่วคราว ป้องกันผ้าเลื่อนหลุดก่อนเย็บถาวร","เพื่อให้ผ้ามีสีสันสวยงาม","เพื่อให้ผ้าหนาขึ้น","เพื่อกันน้ำซึม"]'::jsonb, 0, 'การเนาคือการเย็บตะเข็บห่างๆ ชั่วคราวเพื่อตรึงผ้าให้อยู่ในแนวที่ต้องการ เมื่อเย็บจริงเสร็จแล้วจะเลาะด้ายเนาออก'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] อุปกรณ์ตัดเย็บ: ปลอกนิ้ว', 'medium', 'mcq', '"ปลอกนิ้ว (Thimble)" ที่สวมที่ปลายนิ้วขณะเย็บผ้าด้วยมือ มีประโยชน์อย่างไร?', '["ป้องกันไม่ให้ก้นเข็มแทงปลายนิ้วขณะดันเข็มผ่านผ้าหนา","ช่วยให้ตัดด้ายได้เร็ว","ช่วยสนเข็มได้ง่ายขึ้น","เป็นเครื่องประดับสวยงาม"]'::jsonb, 0, 'ปลอกนิ้วทำจากโลหะหรือพลาสติก ใช้สวมนิ้วกลางเพื่อดันก้นเข็มผ่านเนื้อผ้าหนาโดยไม่เจ็บนิ้ว'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความสะอาดของสถานที่ทำงาน', 'easy', 'mcq', 'เมื่อทำงานประดิษฐ์หรืองานช่างเสร็จสิ้น สิ่งสุดท้ายที่ทุกคนในห้องต้องร่วมมือกันทำคือข้อใด?', '["วิ่งไปโรงอาหารทันที","ช่วยกันเก็บเศษขยะ ทำความสะอาดโต๊ะทำงานและกวาดถูห้องให้เรียบร้อย","โยนอุปกรณ์ไว้บนโต๊ะครู","ปิดไฟและขังเพื่อนไว้ในห้อง"]'::jsonb, 1, 'การทำความสะอาดพื้นที่ทำงาน คัดแยกขยะ และเก็บอุปกรณ์ให้เรียบร้อยหลังทำงานเสร็จเป็นสุขนิสัยที่ดีในการทำงาน'),
('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ประโยชน์ของการมีทักษะการทำงานอาชีพ', 'easy', 'mcq', 'การฝึกทักษะวิชาการงานอาชีพตั้งแต่ระดับประถมศึกษา มีคุณค่าต่อนักเรียนอย่างไรมากที่สุด?', '["ช่วยให้พึ่งพาตนเองได้ ช่วยเหลืองานครอบครัว มีทักษะชีวิต และสามารถนำไปต่อยอดอาชีพในอนาคต","ทำให้ไม่ต้องอ่านหนังสือวิชาอื่น","ทำให้สอบเข้ามหาวิทยาลัยได้โดยไม่ต้องเรียน","ช่วยให้มีชื่อเสียงเป็นดารา"]'::jsonb, 0, 'ช่วยปลูกฝังนิสัยรักการทำงาน การพึ่งพาตนเอง ความคิดริเริ่มสร้างสรรค์ และทักษะการแก้ปัญหาในชีวิตประจำวัน');
